const math = require('mathjs');

const generate = () => {

    const unitSystems = ['si', 'uscs'];

    const units = { 
        "si": { 
            "pressure": "kPa",
            "pressures":"kPa",
            "temperature": "&degC",
            "temperatures": "K",
            "specificEnthalpy":"kJ/kg",
            "specificVolume":"m^3/kg",
        },
        "uscs": {
            "pressure": "psi",
            "pressures":"psf",
            "temperature": "&degF",
            "temperatures": "&degR",
            "specificEnthalpy":"BTU/lb",
            "specificVolume":"ft^3/lb",
        }
    };

    const unitSel = math.randomInt(0, 2); // 0 for SI, 1 for USCS
    const unitsPressure = units[unitSystems[unitSel]].pressure;
    const unitsPressures = units[unitSystems[unitSel]].pressures;
    const unitsTemperature = units[unitSystems[unitSel]].temperature;
    const unitsTemperatures = units[unitSystems[unitSel]].temperatures;
    const unitsSpecificEnthalpy = units[unitSystems[unitSel]].specificEnthalpy;
    const unitsSpecificVolume = units[unitSystems[unitSel]].specificVolume;

    let Pressure1S, T1, T3, T1Old, T3Old, cp, R, pr;
    let Pressure1, Pressure2, Pressure3, Pressure4;
    let T2, T4;
    let v1, v2, v3, v4;
    let W12, W23, W34, W41, Work, Eff, Qin;

    if (unitSel === 0) { // SI Units
       Pressure1S = math.randomInt(175, 225);
       T1 = math.randomInt(85, 115);
       T3 = math.randomInt(575, 625);
       T1Old = T1;
       T3Old = T3;
       T1 = T1 + 273.15; // convert Celsius to Kelvin
       T3 = T3 + 273.15; // convert Celsius to Kelvin
       cp = 1.005; // kJ/(kg K)
       R = 0.287; // kJ/(kg K)
       pr = math.randomInt(7, 12);
       Pressure1 = Pressure1S; // kPa
    }
    else { // USCS Units
        Pressure1S = math.randomInt(25, 35);
        T1 = math.randomInt(180, 220); 
        T3 = math.randomInt(1100, 1120); 
        T1Old = T1;
        T3Old = T3;
        T1 = T1 + 459.67; // convert Fahrenheit to Rankine
        T3 = T3 + 459.67; // convert Fahrenheit to Rankine
        cp = 0.241; // BTU/(lb R)
        R = 53.34; // ft-lbf/(lbm R)
        pr = math.randomInt(7, 12);
        Pressure1 = Pressure1S * 144; // psi to psf
    }

    // Ericsson Cycle states
    T2 = T1; // Isothermal compression 1-2
    T4 = T3; // Isothermal expansion 3-4

    // State 1: (P1, T1, v1)
    v1 = (R * T1) / Pressure1; // v1 = R*T1/P1

    // State 2: (P2, T2, v2) - Isothermal compression (T2=T1), P2 = P1*pr
    Pressure2 = Pressure1 * pr;
    v2 = (R * T2) / Pressure2; // v2 = R*T2/P2 = v1/pr

    // State 3: (P3, T3, v3) - Isobaric heat addition (P3=P2)
    Pressure3 = Pressure2; 
    v3 = (R * T3) / Pressure3; // v3 = R*T3/P3

    // State 4: (P4, T4, v4) - Isothermal expansion (T4=T3), P4 = P1
    Pressure4 = Pressure1;
    v4 = (R * T4) / Pressure4; // v4 = R*T4/P4 = v3*pr

    // Work calculations for each process
    W12 = R * T1 * Math.log(v2 / v1); // Isothermal compression
    W23 = Pressure2 * (v3 - v2); // Isobaric heat addition
    W34 = R * T3 * Math.log(v4 / v3); // Isothermal expansion
    W41 = Pressure1 * (v1 - v4); // Isobaric heat rejection

    // Total Work Output (Net Work)
    Work = W12 + W23 + W34 + W41;

    // Convert work to BTU/lb if USCS
    if (unitSel === 1) {
        Work = Work / 778.169; // ft-lbf/lbm to BTU/lbm
    }

    // Ericsson Cycle Efficiency
    Eff = 1 - (T1 / T3);

    // Heat Input (Qin) derived from Work and Efficiency (Q_in = W_net / Eff)
    // This corresponds to the isothermal heat input at T3: R * T3 * ln(pr)
    Qin = Work / Eff;

    // Rounding to one decimal place as per example
    Work = math.round(Work * 10) / 10;
    Qin = math.round(Qin * 10) / 10;

    // Restore original temperatures for display
    T1 = T1Old;
    T3 = T3Old;

    const data = {
        params: {
            Pressure1S: Pressure1S,
            T1: T1,
            T3: T3,
            pr: pr,
            T1S: T1Old,
            T3S: T3Old,
            T2: T2,
            T4: T4,
            v1: v1,
            v2: v2,
            v3: v3,
            v4: v4,
            cp: cp,
            R: R,
            Eff: Eff,
            W12: W12,
            W23: W23,
            W34: W34,
            W41: W41,
            Pressure1: Pressure1,
            Pressure2: Pressure2,
            Pressure3: Pressure3,
            Pressure4: Pressure4,
            unitsTemperature: unitsTemperature,
            unitsTemperatures: unitsTemperatures,
            unitsPressure: unitsPressure,
            unitsPressures: unitsPressures,
            unitsSpecificEnthalpy: unitsSpecificEnthalpy,
            unitsSpecificVolume: unitsSpecificVolume,
        },
        correct_answers: {
            Work: Work,
            Qin: Qin,
        },
        nDigits: 2,
        sigfigs: 2
    };

    return data;
};

module.exports = {
    generate
};
